/**
 * Cursor-account mode for Origin channels.
 *
 * Origin identity is the signed-in Cursor user (no third-party OAuth). The
 * channel declares repos at definition time; the serve host subscribes
 * `/v0/scm-events` with `provider: "origin"` as that user. Outbound Origin
 * API calls authenticate with the channel's app credentials when configured;
 * hosted v2 deployments instead exchange the Cursor credential for a
 * session (`cursorSessionTokenProvider` in ./api.ts), so reads and writes
 * both run as the deployment service-account principal.
 */
export const CURSOR_ORIGIN_MAX_REPOS = 20;
const CURSOR_ORIGIN_REPO_PATTERN = /^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/;
const runtimeByDefinition = new WeakMap();
export function parseCursorOriginRepoScope(values) {
    const repos = [...new Set(values.map((repo) => repo.trim().toLowerCase()).filter(Boolean))];
    if (repos.length === 0) {
        throw new Error("originChannel({ cursorAccount }) requires at least one repository.");
    }
    if (repos.length > CURSOR_ORIGIN_MAX_REPOS) {
        throw new Error(`originChannel({ cursorAccount }) supports at most ${CURSOR_ORIGIN_MAX_REPOS} repositories.`);
    }
    for (const repo of repos) {
        if (!CURSOR_ORIGIN_REPO_PATTERN.test(repo) || repo.includes("..")) {
            throw new Error(`Invalid Origin repository "${repo}"; expected owner/repo.`);
        }
    }
    return { repos };
}
export function registerOriginCursorAccountRuntime(definition, runtime) {
    runtimeByDefinition.set(definition, runtime);
}
export function getOriginCursorAccountRuntime(definition) {
    return runtimeByDefinition.get(definition);
}
